    [Theory]
    [InlineData(0x80, 7u, 1u, 0x8C00_8A14u)]
    [InlineData(0x7F, 7u, 0u, 0x8C00_8A4Cu)]
    public void FastForwardsIpBinGlyphBitDispatch(byte currentByte, uint bitCountdown, uint bitResult, uint expectedPc)
    {
        var normalMemory = new DreamcastMemory();
        WriteIpBinZeroBitGlyphLoop(normalMemory);
        var fastMemory = new DreamcastMemory();
        WriteIpBinZeroBitGlyphLoop(fastMemory);
        var normal = new Sh4Cpu(normalMemory, 0x8C00_89F6);
        var fast = new Sh4Cpu(fastMemory, 0x8C00_89F6);
        InitializeIpBinZeroBitGlyphLoopState(normalMemory, normal, currentByte, bitCountdown, cellIndex: 27);
        InitializeIpBinZeroBitGlyphLoopState(fastMemory, fast, currentByte, bitCountdown, cellIndex: 27);

        var normalStart = normal.Step();
        var fastStart = fast.Step();
        Assert.Equal(normalStart.Trace, fastStart.Trace);

        Assert.True(fast.TryFastForwardIpBinGlyphBitDispatch(fastStart, 14, out var skippedInstructions));
        Assert.Equal(14UL, skippedInstructions);
        StepMany(normal, skippedInstructions);

        Assert.Equal(normal.State.Pc, fast.State.Pc);
        Assert.Equal(normal.State.R, fast.State.R);
        Assert.Equal(normal.State.T, fast.State.T);
        Assert.Equal(normal.State.InstructionsExecuted, fast.State.InstructionsExecuted);
        Assert.Equal(expectedPc, fast.State.Pc);
        Assert.Equal(bitResult, fastMemory.ReadUInt32(0x7E00_0F54));
    }

    [Theory]
    [InlineData(0xE8, 4u, 33ul, 0x8C00_89F6u, 28u, 3u)]
    [InlineData(0xE0, 4u, 169ul, 0x8C00_8A76u, 32u, 0xFFFF_FFFFu)]
    public void FastForwardsIpBinGlyphBitDispatchAcrossZeroTail(
        byte currentByte,
        uint bitCountdown,
        ulong expectedSkippedInstructions,
        uint expectedPc,
        uint expectedCellIndex,
        uint expectedBitCountdown)
    {
        var normalMemory = new DreamcastMemory();
        WriteIpBinZeroBitGlyphLoop(normalMemory);
        var fastMemory = new DreamcastMemory();
        WriteIpBinZeroBitGlyphLoop(fastMemory);
        var normal = new Sh4Cpu(normalMemory, 0x8C00_89F6);
        var fast = new Sh4Cpu(fastMemory, 0x8C00_89F6);
        InitializeIpBinZeroBitGlyphLoopState(normalMemory, normal, currentByte, bitCountdown, cellIndex: 27);
        InitializeIpBinZeroBitGlyphLoopState(fastMemory, fast, currentByte, bitCountdown, cellIndex: 27);

        var normalStart = normal.Step();
        var fastStart = fast.Step();
        Assert.Equal(normalStart.Trace, fastStart.Trace);

        Assert.True(fast.TryFastForwardIpBinGlyphBitDispatch(fastStart, expectedSkippedInstructions, out var skippedInstructions));
        Assert.Equal(expectedSkippedInstructions, skippedInstructions);
        StepMany(normal, skippedInstructions);

        Assert.Equal(normal.State.Pc, fast.State.Pc);
        Assert.Equal(normal.State.R, fast.State.R);
        Assert.Equal(normal.State.T, fast.State.T);
        Assert.Equal(normal.State.Macl, fast.State.Macl);
        Assert.Equal(normal.State.InstructionsExecuted, fast.State.InstructionsExecuted);
        Assert.Equal(expectedPc, fast.State.Pc);
        Assert.Equal(expectedCellIndex, fastMemory.ReadUInt32(0x7E00_0F4C));
        Assert.Equal(0u, fastMemory.ReadUInt32(0x7E00_0F54));
        Assert.Equal(expectedBitCountdown, fastMemory.ReadUInt32(0x7E00_0F58));
    }

    [Fact]
    public void FastForwardsIpBinGlyphBitDispatchAcrossSetBitAndFollowingZeroTail()
    {
        var normalMemory = new DreamcastMemory();
        WriteIpBinZeroBitGlyphLoop(normalMemory);
        WriteIpBinSetBitGlyphDrawPrefix(normalMemory);
        WriteIpBinSignedDivideQuotientHelper(normalMemory);
        WriteIpBinSignedDivideRemainderHelper(normalMemory);
        WriteIpBinGlyphDrawHelper(normalMemory);
        var fastMemory = new DreamcastMemory();
        WriteIpBinZeroBitGlyphLoop(fastMemory);
        WriteIpBinSetBitGlyphDrawPrefix(fastMemory);
        WriteIpBinSignedDivideQuotientHelper(fastMemory);
        WriteIpBinSignedDivideRemainderHelper(fastMemory);
        WriteIpBinGlyphDrawHelper(fastMemory);
        var normal = new Sh4Cpu(normalMemory, 0x8C00_89F6);
        var fast = new Sh4Cpu(fastMemory, 0x8C00_89F6);
        InitializeIpBinSetBitGlyphDrawPrefixState(normalMemory, normal, cellIndex: 0);
        InitializeIpBinSetBitGlyphDrawPrefixState(fastMemory, fast, cellIndex: 0);
        normalMemory.WriteUInt32(0x7E00_0F44, 1);
        fastMemory.WriteUInt32(0x7E00_0F44, 1);
        normalMemory.Write(0x7E00_0F4B, [1]);
        fastMemory.Write(0x7E00_0F4B, [1]);
        normalMemory.Write(0x7E00_0F63, [0x08]);
        fastMemory.Write(0x7E00_0F63, [0x08]);

        var normalStart = normal.Step();
        var fastStart = fast.Step();
        Assert.Equal(normalStart.Trace, fastStart.Trace);

        Assert.True(fast.TryFastForwardIpBinGlyphBitDispatch(fastStart, 362, out var skippedInstructions));
        Assert.Equal(362UL, skippedInstructions);
        StepMany(normal, skippedInstructions);

        Assert.Equal(normal.State.Pc, fast.State.Pc);
        Assert.Equal(normal.State.Pr, fast.State.Pr);
        Assert.Equal(normal.State.R, fast.State.R);
        Assert.Equal(normal.State.T, fast.State.T);
        Assert.Equal(normal.State.Macl, fast.State.Macl);
        Assert.Equal(normal.State.M, fast.State.M);
        Assert.Equal(normal.State.Q, fast.State.Q);
        Assert.Equal(normal.State.InstructionsExecuted, fast.State.InstructionsExecuted);
        Assert.Equal(0x8C00_8A76u, fast.State.Pc);
        Assert.Equal(4u, fastMemory.ReadUInt32(0x7E00_0F4C));
        Assert.Equal(uint.MaxValue, fastMemory.ReadUInt32(0x7E00_0F58));
        var destination = fastMemory.ReadUInt32(0x7E00_0F34);
        Assert.Equal(0x00C0_C0C0u, fastMemory.ReadUInt32(destination));
    }

    [Theory]
    [InlineData(0x80, 400ul, 0x8C00_89F6u)]
    [InlineData(0x00, 400ul, 0x8C00_8A76u)]
    public void FastForwardsIpBinGlyphByteFetchPrefixAcrossDispatchChain(byte sourceByte, ulong budget, uint expectedPc)
    {
        var normalMemory = new DreamcastMemory();
        WriteIpBinGlyphByteFetchPrefix(normalMemory);
        WriteIpBinZeroBitGlyphLoop(normalMemory);
        WriteIpBinSetBitGlyphDrawPrefix(normalMemory);
        WriteIpBinSignedDivideQuotientHelper(normalMemory);
